"""SEO static pages regression: robots.txt, sitemap.xml, reference/*.html (generated by tools/reference/build_seo_pages.py).
Static checks always; with SVC_KEY set, also checks the pages match the database's public rows exactly. With a URL, renders sample pages
in Chrome and checks the app still opens signed out. Usage: python3 tests/seo_pages_regress.py [URL]"""
import sys, re, json, os, pathlib, random, xml.etree.ElementTree as ET
ROOT = pathlib.Path(__file__).resolve().parents[1]; fails = []
def chk(n, ok, i=""): print(("PASS " if ok else "FAIL ") + n, i); ok or fails.append(n)
SITE = "https://unearthedfinds.com/"
rob = (ROOT / "robots.txt").read_text()
chk("robots.txt allows crawling and names the sitemap", "Allow: /" in rob and "Sitemap: https://unearthedfinds.com/sitemap.xml" in rob and not re.search(r"^Disallow:\s*/\s*$", rob, re.M))
sm = ET.parse(ROOT / "sitemap.xml").getroot(); ns = {"s": "http://www.sitemaps.org/schemas/sitemap/0.9"}
locs = [u.find("s:loc", ns).text for u in sm.findall("s:url", ns)]
chk("sitemap is valid XML with home + reference pages", SITE in locs and SITE + "reference/" in locs and all(SITE + f"reference/{f}.html" in locs for f in ("artifacts", "fossils", "minerals", "texas")))
chk("sitemap has no hash routes, share pages or private paths", not [u for u in locs if "#" in u or "/share/" in u or "/images/" in u or not u.startswith(SITE)])
recs = sorted((ROOT / "reference/r").glob("*.html"))
chk("one sitemap URL per record page", {SITE + "reference/r/" + p.name for p in recs} == {u for u in locs if "/reference/r/" in u}, len(recs))
chk("at least 1,000 record pages", len(recs) >= 1000, len(recs))
need = ['<title>', 'name="description"', 'rel="canonical"', 'property="og:title"', 'property="og:image"', 'name="twitter:card"', 'application/ld+json', '#/try', 'generated by tools/reference/build_seo_pages.py']
bad, ldbad, priv, srct, ids = [], [], [], [], []
PRECISE = re.compile(r"-?\d{1,3}\.\d{4,}\s*,\s*-?\d{1,3}\.\d{4,}|\b(latitude|longitude|GPS|UTM)\b", re.I)
for p in recs + sorted((ROOT / "reference").glob("*.html")):
    t = p.read_text()
    if not all(n in t for n in need): bad.append(p.name)
    for m in re.findall(r'<script type="application/ld\+json">(.*?)</script>', t, re.S):
        try:
            o = json.loads(m)
            if p.parent.name == "r" and not (o.get("license") and o.get("creditText") and o["image"].get("license") and o["image"].get("creditText")): ldbad.append(p.name)
        except Exception: ldbad.append(p.name)
    if re.search(r"ELG-\d{3}|find-photos|/images/ELG|#/find/|exact_location|find_locations", t) or PRECISE.search(re.sub(r"<[^>]+>", " ", t)): priv.append(p.name)
    if p.parent.name == "r":
        m = re.search(r'href="https://unearthedfinds.com/#/reference/([^"]+)"', t); ids.append(m and m.group(1))
        if not re.search(r"<strong>Credit:</strong> .+?</p>", t) or "<strong>License:</strong>" not in t: srct.append(p.name)
chk("every page has title, description, canonical, OG/Twitter, JSON-LD, Try it free", not bad, bad[:3])
chk("record JSON-LD parses and carries license + creditText", not ldbad, ldbad[:3])
chk("no private finds, find photos or precise locations on any page", not priv, priv[:3])
chk("every record page shows credit + license and links into the app", not srct and all(ids), srct[:3])
if os.environ.get("SVC_KEY"):
    sys.path.insert(0, str(ROOT / "tools/reference")); import pc_db, urllib.parse
    rows = pc_db.all_rows("id,data")
    pub = {r["id"] for r in rows if (r.get("data") or {}).get("public") == "1"}
    got = {urllib.parse.unquote(i) for i in ids if i}
    chk("record pages == database public_catalog rows (nothing extra, nothing missing)", got == pub, (len(got), len(pub), sorted(got - pub)[:3]))
    src = {r["id"]: ((r.get("data") or {}).get("catalog") or {}).get("source_title") for r in rows}
    nm = {r["id"]: ((r.get("data") or {}).get("catalog") or {}).get("name") for r in rows}
    diff = [i for i in pub if src.get(i) and src[i] != nm.get(i)]
    hits = [i for i in diff if re.search(r"\bIndians?\b(?! (Ocean|River|Creek|Lake))", src[i]) and any(src[i] in p.read_text() for p in recs)]
    chk("softened wording: museum titles with dated terms never appear", not hits, hits[:3])
else: print("NOTE SVC_KEY not set: skipped database comparison")
idx = (ROOT / "index.html").read_text()
chk("home page has canonical, description, OG image, Twitter tags, JSON-LD", all(s in idx for s in ['rel="canonical" href="https://unearthedfinds.com/"', 'name="description"', 'og:image', 'twitter:title', 'application/ld+json']))
chk("home page verification spot is a placeholder only (no invented token)", not re.search(r'<meta name="(google-site-verification|msvalidate\.01)" content="(?!\.\.\.)', idx))
U = sys.argv[1] if len(sys.argv) > 1 else ""
if U:
    from playwright.sync_api import sync_playwright
    with sync_playwright() as pw:
        b = pw.chromium.launch(executable_path="/usr/bin/google-chrome"); pg = b.new_page(); errs = []
        pg.on("pageerror", lambda e: errs.append(str(e)))
        for path in ["reference/", "reference/texas.html", "reference/r/" + random.Random(1).choice(recs).name]:
            r = pg.goto(U + path); pg.wait_for_load_state("load")
            chk(f"renders {path}", r.status == 200 and pg.locator("h1").count() == 1 and pg.locator("main img").count() >= 1)
        app = pg.goto(U + "#/reference"); pg.wait_for_timeout(1500)
        chk("app shell still loads signed out", app.status == 200 and pg.locator(".side-nav").count() == 1)
        chk("no page errors", not errs, errs[:2]); b.close()
print("\n%d failure(s)" % len(fails)); sys.exit(1 if fails else 0)
